     3	import com.loja.domain.Money;
     4	import com.loja.domain.Region;
     5	import com.loja.domain.ShippingMethod;
     6	import com.loja.integration.TransLogClient;
     7	
     8	import java.math.BigDecimal;
     9	import java.math.RoundingMode;
    10	
    11	public abstract class TransLogShipping implements ShippingStrategy {
    12	
    13	    private final TransLogClient transLogClient;
    14	
    15	    protected TransLogShipping(TransLogClient transLogClient) {
    16	        this.transLogClient = transLogClient;
    17	    }
    18	
    19	    protected abstract String getServiceCode();
    20	
    21	    @Override
    22	    public boolean isAvailable(ShippingContext context) {
    23	        try {
    24	            TransLogClient.QuoteResult result = transLogClient.getQuote(
    25	                context.zipCode(),
    26	                context.totalWeight().toGrams(),
    27	                getServiceCode()
    28	            );
    29	            return result != null && result.priceCents() != null;
    30	        } catch (Exception e) {
    31	            return false;
    32	        }
    33	    }
    34	
    35	    @Override
    36	    public ShippingResult calculateShipping(ShippingContext context) {
    37	        TransLogClient.QuoteResult result = transLogClient.getQuote(
    38	            context.zipCode(),
    39	            context.totalWeight().toGrams(),
    40	            getServiceCode()
    41	        );
    42	
    43	        Money cost = new Money(BigDecimal.valueOf(result.priceCents()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN));
    44	        int baseDays = (int) Math.ceil(result.etaHours() / 24.0);
    45	        int extraDays = getExtraDays(context.region());
    46	
    47	        return new ShippingResult(cost, baseDays + extraDays);
    48	    }
    49	
    50	    private int getExtraDays(Region region) {
    51	        return switch (region) {
    52	            case NORTH -> 3;
    53	            case NORTHEAST -> 2;
    54	            default -> 0;
    55	        };
    56	    }
    57	}
